def transform(wb):
    ws = wb['Sheet1']
    for r in range(83, 13, -1):
        blank = True
        for c in range(6, 12):
            v = ws.cell(row=r, column=c).value
            if v is not None and v != '':
                blank = False
        if blank:
            ws.delete_rows(r, 1)
